// v3.4 party calendar: independent from Plex; private data is filtered in SQL.
async function partyInit(env){
 if(!env.DB)throw Error('D1 binding DB required');
 await communityInit(env);
 await env.DB.prepare('CREATE TABLE IF NOT EXISTS mh_parties (id TEXT PRIMARY KEY,name TEXT NOT NULL,owner_id TEXT NOT NULL,invite_hash TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL)').run();
 await env.DB.prepare('CREATE TABLE IF NOT EXISTS mh_party_members (party_id TEXT NOT NULL,member_id TEXT NOT NULL,joined_at TEXT NOT NULL,PRIMARY KEY(party_id,member_id))').run();
 await env.DB.prepare(`CREATE TABLE IF NOT EXISTS mh_party_events (id TEXT PRIMARY KEY,party_id TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',starts_at TEXT NOT NULL,ends_at TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL)`).run();
 await env.DB.prepare('CREATE TABLE IF NOT EXISTS mh_party_rsvps (event_id TEXT NOT NULL,member_id TEXT NOT NULL,response TEXT NOT NULL,PRIMARY KEY(event_id,member_id))').run();
 await env.DB.prepare('CREATE TABLE IF NOT EXISTS mh_party_polls (id TEXT PRIMARY KEY,party_id TEXT NOT NULL,title TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL)').run();
 await env.DB.prepare('CREATE TABLE IF NOT EXISTS mh_party_poll_options (id TEXT PRIMARY KEY,poll_id TEXT NOT NULL,starts_at TEXT NOT NULL)').run();
 await env.DB.prepare('CREATE TABLE IF NOT EXISTS mh_party_votes (option_id TEXT NOT NULL,member_id TEXT NOT NULL,response TEXT NOT NULL,PRIMARY KEY(option_id,member_id))').run();
}
function partyCode(){const a=crypto.getRandomValues(new Uint8Array(12));return 'PARTY-'+Array.from(a,b=>b.toString(16).padStart(2,'0')).join('').toUpperCase();}
async function partyRoute(req,env,u){
 await partyInit(env);
 const member=await communityMember(req,env);
 if(req.method==='GET'&&u.pathname==='/api/party/me'){
  const parties=member?(await env.DB.prepare('SELECT p.id,p.name,p.owner_id AS ownerId FROM mh_parties p JOIN mh_party_members m ON m.party_id=p.id WHERE m.member_id=? ORDER BY p.created_at').bind(member.id).all()).results||[]:[];
  return json({member,parties});
 }
 if(req.method==='GET'&&u.pathname==='/api/party/data'){
  if(!member)return json({events:[],polls:[]});
  const events=(await env.DB.prepare('SELECT e.id,e.party_id AS partyId,e.title,e.description,e.starts_at AS startsAt,e.ends_at AS endsAt,e.created_by AS createdBy FROM mh_party_events e JOIN mh_party_members m ON m.party_id=e.party_id WHERE m.member_id=? ORDER BY e.starts_at LIMIT 300').bind(member.id).all()).results||[];
  const polls=(await env.DB.prepare('SELECT p.id,p.party_id AS partyId,p.title,p.created_by AS createdBy FROM mh_party_polls p JOIN mh_party_members m ON m.party_id=p.party_id WHERE m.member_id=? ORDER BY p.created_at DESC LIMIT 100').bind(member.id).all()).results||[];
  const eventIds=events.map(e=>e.id),pollIds=polls.map(p=>p.id);
  const rsvps=eventIds.length?(await env.DB.prepare('SELECT r.event_id AS eventId,r.response,m.display_name AS name,r.member_id AS memberId FROM mh_party_rsvps r JOIN mh_members m ON m.id=r.member_id WHERE r.event_id IN ('+eventIds.map(()=>'?').join(',')+')').bind(...eventIds).all()).results||[]:[];
  const options=pollIds.length?(await env.DB.prepare('SELECT id,poll_id AS pollId,starts_at AS startsAt FROM mh_party_poll_options WHERE poll_id IN ('+pollIds.map(()=>'?').join(',')+') ORDER BY starts_at').bind(...pollIds).all()).results||[]:[];
  const optionIds=options.map(o=>o.id);
  const votes=optionIds.length?(await env.DB.prepare('SELECT v.option_id AS optionId,v.response,m.display_name AS name,v.member_id AS memberId FROM mh_party_votes v JOIN mh_members m ON m.id=v.member_id WHERE v.option_id IN ('+optionIds.map(()=>'?').join(',')+')').bind(...optionIds).all()).results||[]:[];
  return json({events:events.map(e=>({...e,canDelete:e.createdBy===member.id,rsvps:rsvps.filter(r=>r.eventId===e.id).map(r=>({name:r.name,response:r.response,mine:r.memberId===member.id}))})),polls:polls.map(p=>({...p,canDelete:p.createdBy===member.id,options:options.filter(o=>o.pollId===p.id).map(o=>({...o,votes:votes.filter(v=>v.optionId===o.id).map(v=>({name:v.name,response:v.response,mine:v.memberId===member.id}))}))}))});
 }
 if(req.method!=='POST')return err('Method not allowed',405);
 if(!adminOrigin(req))return err('Invalid request origin',403);
 const raw=await req.text();if(raw.length>4096)return err('Request too large',413);
 let data;try{data=JSON.parse(raw)}catch{return err('Invalid JSON',400)}
 if(u.pathname==='/api/party/identity'){
  if(member)return json({member});
  const name=String(data.name||'').trim();if(name.length<2||name.length>40)return err('Display name must be 2–40 characters',400);
  const token=randomId(),id=crypto.randomUUID();await env.DB.prepare('INSERT INTO mh_members(id,display_name,token_hash,created_at) VALUES(?,?,?,?)').bind(id,name,await hash(token),new Date().toISOString()).run();
  return json({token,member:{id,display_name:name}});
 }
 if(!member)return err('Create your party identity first',401);
 if(u.pathname==='/api/party/profile'){
  const name=String(data.name||'').trim();if(name.length<2||name.length>40)return err('Display name must be 2–40 characters',400);
  await env.DB.prepare('UPDATE mh_members SET display_name=? WHERE id=?').bind(name,member.id).run();
  return json({ok:true,member:{...member,display_name:name}});
 }
 if(u.pathname==='/api/party/create'){
  const name=String(data.name||'').trim();if(name.length<2||name.length>80)return err('Party name must be 2–80 characters',400);
  const id=crypto.randomUUID(),code=partyCode(),now=new Date().toISOString();
  await env.DB.batch([env.DB.prepare('INSERT INTO mh_parties(id,name,owner_id,invite_hash,created_at) VALUES(?,?,?,?,?)').bind(id,name,member.id,await hash(code),now),env.DB.prepare('INSERT INTO mh_party_members(party_id,member_id,joined_at) VALUES(?,?,?)').bind(id,member.id,now)]);
  return json({id,code});
 }
 if(u.pathname==='/api/party/join'){
  const code=String(data.code||'').trim().toUpperCase();if(!/^PARTY-[A-F0-9]{24}$/.test(code))return err('Invalid party code',400);
  const p=await env.DB.prepare('SELECT id FROM mh_parties WHERE invite_hash=?').bind(await hash(code)).first();if(!p)return err('Party code not found',404);
  await env.DB.prepare('INSERT OR IGNORE INTO mh_party_members(party_id,member_id,joined_at) VALUES(?,?,?)').bind(p.id,member.id,new Date().toISOString()).run();return json({ok:true});
 }
 const partyId=String(data.partyId||'');
 if(u.pathname==='/api/party/leave'){
  const p=await env.DB.prepare('SELECT owner_id AS ownerId FROM mh_parties WHERE id=?').bind(partyId).first();if(!p)return err('Party not found',404);
  if(p.ownerId===member.id)return err('Party owner cannot leave; transfer or deletion is not yet supported',409);
  await env.DB.prepare('DELETE FROM mh_party_members WHERE party_id=? AND member_id=?').bind(partyId,member.id).run();return json({ok:true});
 }
 if(u.pathname==='/api/party/rotate'){
  const p=await env.DB.prepare('SELECT owner_id AS ownerId FROM mh_parties WHERE id=?').bind(partyId).first();if(!p||p.ownerId!==member.id)return err('Only the party owner can rotate codes',403);
  const code=partyCode();await env.DB.prepare('UPDATE mh_parties SET invite_hash=? WHERE id=?').bind(await hash(code),partyId).run();return json({code});
 }
 if(u.pathname==='/api/party/event'&&data.action==='rsvp'){
  const event=await env.DB.prepare('SELECT e.id FROM mh_party_events e JOIN mh_party_members m ON m.party_id=e.party_id WHERE e.id=? AND m.member_id=?').bind(String(data.eventId||''),member.id).first();if(!event)return err('Event unavailable',404);
  if(!['Going','Maybe','Unavailable'].includes(data.response))return err('Invalid RSVP',400);
  await env.DB.prepare('INSERT INTO mh_party_rsvps(event_id,member_id,response) VALUES(?,?,?) ON CONFLICT(event_id,member_id) DO UPDATE SET response=excluded.response').bind(event.id,member.id,data.response).run();return json({ok:true});
 }
 if(u.pathname==='/api/party/poll'&&data.action==='vote'){
  const opt=await env.DB.prepare('SELECT o.id FROM mh_party_poll_options o JOIN mh_party_polls p ON p.id=o.poll_id JOIN mh_party_members m ON m.party_id=p.party_id WHERE o.id=? AND m.member_id=?').bind(String(data.optionId||''),member.id).first();if(!opt)return err('Poll option unavailable',404);
  if(!['Going','Maybe','Unavailable'].includes(data.response))return err('Invalid vote',400);
  await env.DB.prepare('INSERT INTO mh_party_votes(option_id,member_id,response) VALUES(?,?,?) ON CONFLICT(option_id,member_id) DO UPDATE SET response=excluded.response').bind(opt.id,member.id,data.response).run();return json({ok:true});
 }
 if(u.pathname==='/api/party/event'&&data.action==='delete'){
  const ev=await env.DB.prepare('SELECT created_by AS createdBy FROM mh_party_events WHERE id=?').bind(String(data.id||'')).first();if(!ev||ev.createdBy!==member.id)return err('Only the creator can delete this event',403);
  await env.DB.batch([env.DB.prepare('DELETE FROM mh_party_rsvps WHERE event_id=?').bind(data.id),env.DB.prepare('DELETE FROM mh_party_events WHERE id=?').bind(data.id)]);return json({ok:true});
 }
 if(u.pathname==='/api/party/poll'&&data.action==='delete'){
  const poll=await env.DB.prepare('SELECT created_by AS createdBy FROM mh_party_polls WHERE id=?').bind(String(data.id||'')).first();if(!poll||poll.createdBy!==member.id)return err('Only the creator can delete this poll',403);
  await env.DB.batch([env.DB.prepare('DELETE FROM mh_party_votes WHERE option_id IN (SELECT id FROM mh_party_poll_options WHERE poll_id=?)').bind(data.id),env.DB.prepare('DELETE FROM mh_party_poll_options WHERE poll_id=?').bind(data.id),env.DB.prepare('DELETE FROM mh_party_polls WHERE id=?').bind(data.id)]);return json({ok:true});
 }
 const allowed=await env.DB.prepare('SELECT 1 AS yes FROM mh_party_members WHERE party_id=? AND member_id=?').bind(partyId,member.id).first();if(!allowed)return err('Not a member of that party',403);
 if(u.pathname==='/api/party/event'){
  const title=String(data.title||'').trim(),description=String(data.description||'').trim(),starts=communityDate(data.startsAt),ends=data.endsAt?communityDate(data.endsAt):null;
  if(!title||title.length>120||description.length>1000||!starts||(data.endsAt&&!ends)||(ends&&ends<=starts))return err('Invalid event details',400);
  await env.DB.prepare('INSERT INTO mh_party_events(id,party_id,title,description,starts_at,ends_at,created_by,created_at) VALUES(?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),partyId,title,description,starts,ends,member.id,new Date().toISOString()).run();return json({ok:true});
 }
 if(u.pathname==='/api/party/poll'){
  const title=String(data.title||'').trim(),dates=String(data.dates||'').split(/[\n,]+/).map(s=>s.trim()).filter(Boolean);
  if(!title||title.length>120||dates.length<2||dates.length>10||new Set(dates).size!==dates.length||dates.some(d=>!communityDate(d)))return err('Title and 2–10 unique date/time options required',400);
  const id=crypto.randomUUID();await env.DB.prepare('INSERT INTO mh_party_polls(id,party_id,title,created_by,created_at) VALUES(?,?,?,?,?)').bind(id,partyId,title,member.id,new Date().toISOString()).run();await env.DB.batch(dates.map(d=>env.DB.prepare('INSERT INTO mh_party_poll_options(id,poll_id,starts_at) VALUES(?,?,?)').bind(crypto.randomUUID(),id,d)));return json({ok:true});
 }
 return err('Not found',404);
}


// Admin-managed on-site presentation; D1 is the shared source of truth.
async function presentationRoute(req,env){
 if(!env.DB)return err('Database unavailable',503);
 await env.DB.prepare('CREATE TABLE IF NOT EXISTS mh_presentation (id INTEGER PRIMARY KEY CHECK(id=1), value TEXT NOT NULL)').run();
 if(req.method==='GET'){
  const row=await env.DB.prepare('SELECT value FROM mh_presentation WHERE id=1').first();
  let value={};try{value=row?JSON.parse(row.value):{}}catch{}
  const now=Date.now();
  const active=a=>Array.isArray(a)?a.filter(x=>x&&(!x.expiresAt||Date.parse(x.expiresAt)>now)):[];
  return json({welcome:String(value.welcome||'').slice(0,500),banners:active(value.banners),cards:active(value.cards),timers:active(value.timers),...(await adminSession(req,env)?{all:value}:{})});
 }
 if(req.method!=='POST')return err('Method not allowed',405);
 if(!adminOrigin(req)||!await adminSession(req,env))return err('Admin login required',403);
 const raw=await req.text();if(raw.length>25000)return err('Request too large',413);
 let d;try{d=JSON.parse(raw)}catch{return err('Invalid JSON',400)}
 const row=await env.DB.prepare('SELECT value FROM mh_presentation WHERE id=1').first();let v={};try{v=row?JSON.parse(row.value):{}}catch{}
 const validText=(x,max)=>typeof x==='string'&&x.trim().length>0&&x.length<=max;
 const validDate=x=>!x||(typeof x==='string'&&Number.isFinite(Date.parse(x)));
 if(d.action==='welcome'){
  if(typeof d.welcome!=='string'||d.welcome.length>500)return err('Welcome message too long',400);
  v.welcome=d.welcome.trim();
 }else if(['banner','card','timer'].includes(d.action)){
  const kind={banner:'banners',card:'cards',timer:'timers'}[d.action];v[kind]=Array.isArray(v[kind])?v[kind]:[];
  if(d.operation==='delete')v[kind]=v[kind].filter(x=>x.id!==d.id);
  else{
   if(v[kind].length>=20)return err('Maximum 20 items of each type',400);
   if(!validText(d.title,100)||!validDate(d.expiresAt))return err('Invalid title or expiration',400);
   const item={id:crypto.randomUUID(),title:d.title.trim(),expiresAt:d.expiresAt||null};
   if(kind==='banners'||kind==='cards'){
    if(typeof d.body!=='string'||d.body.length>1500)return err('Message too long',400);
    item.body=d.body.trim();
   }
   if(kind==='timers'){
    const t=Date.parse(d.deadline);
    if(!Number.isFinite(t)||t<Date.now()-86400000||t>Date.now()+366*86400000)return err('Deadline must be a valid date within one year',400);
    item.deadline=new Date(t).toISOString();
    if(d.repeat==='weekly'){item.repeat='weekly';item.timezone=typeof d.timezone==='string'?d.timezone.slice(0,80):'UTC';}
   }
   v[kind].push(item);
  }
 }else return err('Unknown action',400);
 await env.DB.prepare('INSERT INTO mh_presentation(id,value) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET value=excluded.value').bind(JSON.stringify(v)).run();
 return json({ok:true});
}


// v3.4.12 admin-only dashboard configuration backup (no credentials or user records).
async function configurationBackupRoute(req,env){
 if(!env.DB)return err('Database unavailable',503);
 if((req.method!=='GET'&&!adminOrigin(req))||!await adminSession(req,env))return err('Administrator access required',403);
 await adminInit(env);
 const settingsKeys=['name','tagline','accent','icon','customSvg','customSvgData','homeLayout'];
 const tables=[['mh_dashboard_settings','SELECT key,value FROM mh_dashboard_settings'],['mh_presentation','SELECT id,value FROM mh_presentation'],['mh_announcements','SELECT id,title,body,pinned,banner,expires_at,created_at FROM mh_announcements'],['mh_quick_links','SELECT * FROM mh_quick_links'],['mh_quick_link_groups','SELECT id,title,position,links_json,created_at FROM mh_quick_link_groups']];
 // Schema varies between older installations; a missing optional table becomes an empty collection.
 if(req.method==='GET'){
  const out={format:'screenden-config',version:1,exportedAt:new Date().toISOString(),data:{}};
  for(const [name,sql] of tables){try{const r=await env.DB.prepare(sql).all();out.data[name]=(r.results||[]).filter(x=>name!=='mh_dashboard_settings'||settingsKeys.includes(x.key));}catch{out.data[name]=[];}}
  return json(out);
 }
 if(req.method!=='POST')return err('Method not allowed',405);
 const raw=await req.text();if(raw.length>200000)return err('Backup too large',413);
 let backup;try{backup=JSON.parse(raw)}catch{return err('Invalid JSON',400)}
 if(!['screenden-config','media-hub-config'].includes(backup?.format)||backup.version!==1||!backup.data||typeof backup.data!=='object')return err('Invalid backup format',400);
 const d=backup.data;
 if(d.mh_quick_link_groups===undefined)d.mh_quick_link_groups=[]; // Older exports predate dropdown groups.
 for(const key of Object.keys(d))if(!tables.some(([name])=>name===key))return err('Unexpected backup section',400);
 for(const [name] of tables)if(!Array.isArray(d[name])||d[name].length>100)return err('Invalid backup entries',400);
 for(const x of d.mh_dashboard_settings){if(!x||!settingsKeys.includes(x.key)||typeof x.value!=='string'||x.value.length>50000)return err('Invalid setting',400);if(x.key==='homeLayout'&&!validateHomeLayout(JSON.parse(x.value)))return err('Invalid layout',400);if(x.key==='customSvgData'&&!validateBrandSvg(x.value))return err('Invalid logo',400);}
 for(const x of d.mh_presentation){if(x.id!==1||typeof x.value!=='string'||x.value.length>100000)return err('Invalid presentation',400);try{const v=JSON.parse(x.value);if(!v||typeof v!=='object'||['banners','cards','timers'].some(k=>v[k]&&!Array.isArray(v[k])))return err('Invalid presentation',400)}catch{return err('Invalid presentation JSON',400)}}
 for(const x of d.mh_announcements){if(typeof x.id!=='string'||typeof x.title!=='string'||typeof x.body!=='string'||x.title.length>200||x.body.length>5000)return err('Invalid announcement',400)}
 // Quick links are not restored when schema cannot be safely validated.
 const count=d.mh_dashboard_settings.length+d.mh_presentation.length+d.mh_announcements.length;
 if(count>200)return err('Too many records',400);
 // All validated before any mutation. Do not delete unrelated rows.
 try{await env.DB.prepare("ALTER TABLE mh_announcements ADD COLUMN banner INTEGER NOT NULL DEFAULT 0").run();}catch{}
 await env.DB.batch([
  ...d.mh_dashboard_settings.map(x=>env.DB.prepare('INSERT INTO mh_dashboard_settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').bind(x.key,x.value)),
  ...d.mh_presentation.map(x=>env.DB.prepare('INSERT INTO mh_presentation(id,value) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET value=excluded.value').bind(x.value)),
  ...d.mh_announcements.map(x=>env.DB.prepare('INSERT OR REPLACE INTO mh_announcements(id,title,body,pinned,banner,expires_at,created_at) VALUES(?,?,?,?,?,?,?)').bind(x.id,x.title,x.body,Number(x.pinned)?1:0,Number(x.banner)?1:0,x.expires_at||null,x.created_at||new Date().toISOString()))
 ]);
 return json({ok:true,restored:count,quickLinksRestored:false});
}

