 const type=String(d.type||'file'),visibility=String(d.visibility||'all');
 if(!['apk','pdf','file','website'].includes(type)||!['all','tv','standard','hidden'].includes(visibility))return err('Invalid resource type or visibility',400);
 const position=Number.isFinite(Number(d.position))?Math.max(-10000,Math.min(10000,Math.trunc(Number(d.position)))):0;
