// Configurable dashboard shortcuts; only admin sessions may mutate them.
function rouletteMediaItem(v,server){
 if(!['movie','show'].includes(v.type)||!/^\d{1,15}$/.test(String(v.ratingKey||'')))return null;
 const ratingKey=String(v.ratingKey);
 return {title:String(v.title||'Untitled').slice(0,200),year:Number(v.year)||null,type:v.type,summary:String(v.summary||'').slice(0,500),thumb:String(v.thumb||'').slice(0,500),machine:server.machine,serverName:server.name,ratingKey,link:'https://app.plex.tv/desktop/#!/server/'+encodeURIComponent(server.machine)+'/details?key='+encodeURIComponent('/library/metadata/'+ratingKey)};
}
async function rouletteRoute(req,env,u,s){
 if(req.method!=='GET')return err('Method not allowed',405);
 const kind=u.searchParams.get('kind')||'movie',machine=u.searchParams.get('server')||'',search=u.pathname.endsWith('/search');
 if(!['movie','show','both'].includes(kind))return err('Invalid wheel media type',400);
 if(!/^[a-zA-Z0-9_-]{8,128}$/.test(machine))return err('Select a Plex server first',400);
 const q=String(u.searchParams.get('q')||'').trim().slice(0,100);
 if(search&&q.length<2)return err('Enter at least two characters to search',400);
 const servers=await getServers(env,s.token),server=servers.find(x=>x.machine===machine);
 if(!server)return err('Selected server is not accessible',403);
 let items=[],connected=false,partial=false;
 const raceWin=await plexRace(server,async base=>{
  let sections;try{sections=(await xmlPlex(base+'/library/sections',server.token))?.MediaContainer?.Directory||[];connected=true;}catch{return null;}
  const eligible=sections.filter(x=>['movie','show'].includes(x.type)&&(kind==='both'||x.type===kind)&&/^\d+$/.test(String(x.key)));
  partial=eligible.length>12;
  const results=await Promise.allSettled(eligible.slice(0,12).map(async section=>{
   const filter=search?'title='+encodeURIComponent(q):'type='+(section.type==='movie'?'1':'2')+'&sort=random';
   const payload=await xmlPlex(base+'/library/sections/'+section.key+'/all?'+filter+'&X-Plex-Container-Start=0&X-Plex-Container-Size='+(search?30:8),server.token);
   return (payload?.MediaContainer?.Metadata||[]).filter(v=>['movie','show'].includes(v.type)&&(kind==='both'||v.type===kind)&&(!search||String(v.title||'').toLowerCase().includes(q.toLowerCase()))).map(v=>rouletteMediaItem(v,server)).filter(Boolean);
  }));
  const partialHere=partial||results.some(r=>r.status==='rejected');
  const foundHere=results.flatMap(r=>r.status==='fulfilled'?r.value:[]);
  return (foundHere.length||!eligible.length)?{items:foundHere,partial:partialHere}:null;
 });
 if(raceWin){items=raceWin.value.items;partial=raceWin.value.partial;}
 if(!connected)return err('Could not read libraries from the selected Plex server',502);
 const unique=[...new Map(items.map(x=>[x.machine+':'+x.ratingKey,x])).values()];
 if(!search){for(let i=unique.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[unique[i],unique[j]]=[unique[j],unique[i]];}}
 return json({items:unique.slice(0,search?30:8),partial,warning:partial?'Some libraries could not be fully scanned. Results may be incomplete.':''});
}

async function quickLinkGroupsInit(env){
 await env.DB.prepare("CREATE TABLE IF NOT EXISTS mh_quick_link_groups (id TEXT PRIMARY KEY, title TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, links_json TEXT NOT NULL, created_at TEXT NOT NULL)").run();
}
function validSidebarUrl(value){
 if(typeof value!=='string'||value.length>1024)return null;
 try{const u=new URL(value.trim());return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:null;}catch{return null;}
}
async function quickLinkGroupWrite(req,env,d){
 if(d.id!==undefined&&typeof d.id!=='string')return err('Invalid group ID',400);
 const id=typeof d.id==='string'?d.id:'';
 if(d.action==='group-delete'){
  if(!id||id.length>100)return err('Invalid group ID',400);
  const r=await env.DB.prepare('DELETE FROM mh_quick_link_groups WHERE id=?').bind(id).run();
  return r.meta?.changes?json({ok:true}):err('Link group not found',404);
 }
 const title=typeof d.title==='string'?d.title.trim():'';
 if(!title||title.length>80||!Array.isArray(d.links)||d.links.length<1||d.links.length>20||id.length>100)return err('A group needs a name and 1–20 links',400);
 const links=[];
 for(const item of d.links){
  if(!item||typeof item!=='object')return err('Invalid group link',400);
  const name=typeof item.title==='string'?item.title.trim():'',description=typeof item.description==='string'?item.description.trim():'';
  const url=validSidebarUrl(item.url);
  if(!name||name.length>80||description.length>200||!url)return err('Each group link needs a name and ordinary HTTP(S) URL without embedded credentials',400);
  links.push({title:name,url,description});
 }
 const position=Number.isSafeInteger(Number(d.position))?Math.max(-10000,Math.min(10000,Number(d.position))):0;
 if(id){
  const r=await env.DB.prepare('UPDATE mh_quick_link_groups SET title=?,position=?,links_json=? WHERE id=?').bind(title,position,JSON.stringify(links),id).run();
  return r.meta?.changes?json({ok:true,id}):err('Link group not found',404);
 }
 const count=await env.DB.prepare('SELECT COUNT(*) AS n FROM mh_quick_link_groups').first();
 if(Number(count?.n)>=20)return err('Maximum 20 link groups',400);
 const newId=crypto.randomUUID();
 await env.DB.prepare('INSERT INTO mh_quick_link_groups(id,title,position,links_json,created_at) VALUES(?,?,?,?,?)').bind(newId,title,position,JSON.stringify(links),new Date().toISOString()).run();
 return json({ok:true,id:newId});
}

