// Scheduled Worker trigger and visitor requests share this public status-page reader.
async function kumaPublicSnapshot(env){
 const raw=String(env.KUMA_STATUS_URL||'').trim();
 if(!raw)return null;
 const page=new URL(raw);
 if(page.protocol!=='https:'||page.username||page.password||page.port||page.hash)throw Error('Invalid Kuma status URL');
 const slug=page.pathname.match(/\/status\/([a-zA-Z0-9_-]+)\/?$/)?.[1];
 if(!slug)throw Error('Expected /status/slug URL');
 const get=async path=>{
  const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),7500);
  try{
   const r=await fetch(page.origin+path,{signal:controller.signal,redirect:'manual',headers:{Accept:'application/json'}});
   if(!r.ok)throw Error('Uptime Kuma HTTP '+r.status);
   return await r.json();
  }finally{clearTimeout(timer)}
 };
 const results=await Promise.allSettled([get('/api/status-page/'+encodeURIComponent(slug)),get('/api/status-page/heartbeat/'+encodeURIComponent(slug))]);
 if(results[0].status!=='fulfilled')throw Error('Monitor list request failed: '+String(results[0].reason?.message||results[0].reason));
 const detail=results[0].value;
 const heartbeats=results[1].status==='fulfilled'?results[1].value:{};
 return {page,groups:Array.isArray(detail.publicGroupList)?detail.publicGroupList:[],beats:heartbeats.heartbeatList||{},uptime:heartbeats.uptimeList||{},heartbeatWarning:results[1].status==='rejected'?'Heartbeat history unavailable: '+String(results[1].reason?.message||results[1].reason):null};
}
async function kumaScheduledPoll(env){
 if(!env.KUMA_STATUS_URL)return {skipped:'KUMA_STATUS_URL not configured'};
 if(!env.DB)throw Error('D1 DB binding required for scheduled incident archive');
 const snapshot=await kumaPublicSnapshot(env);
 if(snapshot.heartbeatWarning)throw Error(snapshot.heartbeatWarning);
 // Notify the admin when a monitor flips state (v3.6.36): compare the newest
 // archived event per monitor before and after this poll's ingest.
 const latest=async()=>{const rows=await env.DB.prepare('SELECT monitor_id,monitor_name,status,event_time FROM mh_kuma_status_events ORDER BY event_time DESC').all().catch(()=>({results:[]}));const map=new Map();for(const r of rows.results||[])if(!map.has(r.monitor_id))map.set(r.monitor_id,r);return map;};
 const before=await latest();
 await kumaCronArchiveIngest(env,snapshot.groups,snapshot.beats);
 const after=await latest();
 for(const [id,now] of after){
  const prev=before.get(id);
  if(prev&&prev.status!==now.status&&Date.now()-new Date(now.event_time).getTime()<20*60*1000){
   const down=Number(now.status)===0;
   await notify(env,{audience:'admin',category:'server',title:(down?'🔴 ':'🟢 ')+now.monitor_name+(down?' is down':' is back up'),body:'Uptime Kuma reported a state change at '+now.event_time+'.',page:'Service History'});
  }
 }
 return {ok:true,monitors:snapshot.groups.reduce((n,g)=>n+(g.monitorList||[]).length,0)};
}
async function kumaCronArchiveIngest(env,groups,beats){
 await env.DB.prepare('CREATE TABLE IF NOT EXISTS mh_kuma_status_events (monitor_id TEXT NOT NULL, monitor_name TEXT NOT NULL, event_time TEXT NOT NULL, status INTEGER NOT NULL, PRIMARY KEY(monitor_id,event_time,status))').run();
 const writes=[];
 for(const group of groups)for(const monitor of (group.monitorList||[])){
  if(monitor.id==null)continue;
  const id=String(monitor.id),name=String(monitor.name||'Unnamed monitor').slice(0,120);
  const history=(Array.isArray(beats[id])?beats[id]:[]).slice(-120);
  let prior=null;
  for(const beat of history){
   const status=Number(beat.status),time=Date.parse(beat.time||'');
   if(![0,1].includes(status)||!Number.isFinite(time))continue;
   if(prior!==status&&(status===0||prior===0))writes.push(env.DB.prepare('INSERT OR IGNORE INTO mh_kuma_status_events (monitor_id,monitor_name,event_time,status) VALUES (?,?,?,?)').bind(id,name,new Date(time).toISOString(),status));
   prior=status;
  }
 }
 for(let i=0;i<writes.length;i+=50)await env.DB.batch(writes.slice(i,i+50));
}

