 try{r=await fetch(OMBI_LAB_URL+(d.kind==='tv'?'/api/v2/Requests/tv':'/api/v1/Request/movie'),{method:'POST',headers:{Authorization:'Bearer '+sess.token,'content-type':'application/json',Accept:'application/json'},body:JSON.stringify(body),redirect:'manual',signal:AbortSignal.timeout(20000)});}catch(e){return err('Ombi request transport failed: '+String(e?.message||e).slice(0,140),502)}
