// -- Web Push plumbing (RFC 8292 VAPID + RFC 8291 aes128gcm) --
const b64u={enc(bytes){let s='';for(const b of bytes)s+=String.fromCharCode(b);return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');},dec(text){const pad='='.repeat((4-text.length%4)%4);const bin=atob(text.replace(/-/g,'+').replace(/_/g,'/')+pad);const out=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)out[i]=bin.charCodeAt(i);return out;}};
async function vapidKeys(env){
 await env.DB.prepare('CREATE TABLE IF NOT EXISTS mh_dashboard_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)').run();
 const r=await env.DB.prepare("SELECT key,value FROM mh_dashboard_settings WHERE key IN ('vapidPublic','vapidPrivate')").all();
 const values=Object.fromEntries((r.results||[]).map(x=>[x.key,x.value]));
 if(!values.vapidPublic||!values.vapidPrivate)return null;
 return {publicKey:values.vapidPublic,privateJwk:JSON.parse(values.vapidPrivate)};
}
async function vapidGenerate(env){
 await env.DB.prepare('CREATE TABLE IF NOT EXISTS mh_dashboard_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)').run();
 const pair=await crypto.subtle.generateKey({name:'ECDSA',namedCurve:'P-256'},true,['sign','verify']);
 const jwk=await crypto.subtle.exportKey('jwk',pair.privateKey);
 const pub=await crypto.subtle.exportKey('raw',pair.publicKey);
 const values={vapidPublic:b64u.enc(new Uint8Array(pub)),vapidPrivate:JSON.stringify({kty:jwk.kty,crv:jwk.crv,x:jwk.x,y:jwk.y,d:jwk.d})};
 await env.DB.batch(Object.entries(values).map(([k,v])=>env.DB.prepare('INSERT INTO mh_dashboard_settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').bind(k,v)));
 return values.vapidPublic;
}
async function vapidJwt(env,keys,audience){
 const header=b64u.enc(new TextEncoder().encode(JSON.stringify({typ:'JWT',alg:'ES256'})));
 const payload=b64u.enc(new TextEncoder().encode(JSON.stringify({aud:audience,exp:Math.floor(Date.now()/1000)+12*3600,sub:'https://media-hub.local/'})));
 const key=await crypto.subtle.importKey('jwk',keys.privateJwk,{name:'ECDSA',namedCurve:'P-256'},false,['sign']);
 const sig=await crypto.subtle.sign({name:'ECDSA',hash:'SHA-256'},key,new TextEncoder().encode(header+'.'+payload));
 return header+'.'+payload+'.'+b64u.enc(new Uint8Array(sig));
}
async function hkdf(ikm,salt,info,length){
 const key=await crypto.subtle.importKey('raw',ikm,'HKDF',false,['deriveBits']);
 return new Uint8Array(await crypto.subtle.deriveBits({name:'HKDF',hash:'SHA-256',salt,info},key,length*8));
}
async function pushEncrypt(sub,payloadText,serverPair){
 const uaPublic=b64u.dec(sub.p256dh),auth=b64u.dec(sub.auth);
 const uaKey=await crypto.subtle.importKey('raw',uaPublic,{name:'ECDH',namedCurve:'P-256'},false,[]);
 const shared=new Uint8Array(await crypto.subtle.deriveBits({name:'ECDH',public:uaKey},serverPair.privateKey,256));
 const serverPublic=new Uint8Array(await crypto.subtle.exportKey('raw',serverPair.publicKey));
 const info=new Uint8Array([0x57,0x65,0x62,0x50,0x75,0x73,0x68,0x3a,0x20,0x69,0x6e,0x66,0x6f,0x00]); // "WebPush: info\0"
 const ikmInfo=new Uint8Array(info.length+uaPublic.length+serverPublic.length);ikmInfo.set(info);ikmInfo.set(uaPublic,info.length);ikmInfo.set(serverPublic,info.length+uaPublic.length);
 const ikm=await hkdf(shared,auth,ikmInfo,32);
 const salt=crypto.getRandomValues(new Uint8Array(16));
 const cek=await hkdf(ikm,salt,new TextEncoder().encode('Content-Encoding: aes128gcm\0'),16);
 const nonce=await hkdf(ikm,salt,new TextEncoder().encode('Content-Encoding: nonce\0'),12);
 const plain=new Uint8Array(new TextEncoder().encode(payloadText).length+1);
 plain.set(new TextEncoder().encode(payloadText));plain[plain.length-1]=2; // single-record padding delimiter
 const aesKey=await crypto.subtle.importKey('raw',cek,{name:'AES-GCM'},false,['encrypt']);
 const cipher=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv:nonce,tagLength:128},aesKey,plain));
 const body=new Uint8Array(16+4+1+serverPublic.length+cipher.length);
 body.set(salt);new DataView(body.buffer).setUint32(16,4096);body[20]=serverPublic.length;body.set(serverPublic,21);body.set(cipher,21+serverPublic.length);
 return body;
}
async function pushSend(env,keys,sub,payload){
 try{
  const endpoint=new URL(sub.endpoint);
  const serverPair=await crypto.subtle.generateKey({name:'ECDH',namedCurve:'P-256'},true,['deriveBits']);
  const body=await pushEncrypt(sub,JSON.stringify(payload),serverPair);
  const jwt=await vapidJwt(env,keys,endpoint.origin);
  const r=await fetch(sub.endpoint,{method:'POST',headers:{'Authorization':'vapid t='+jwt+', k='+keys.publicKey,'Content-Encoding':'aes128gcm','Content-Type':'application/octet-stream','TTL':'86400','Urgency':'high'},body});
  await setSetting(env,'pushLastStatus',String(r.status)).catch(()=>{});await setSetting(env,'pushLastAt',String(Date.now())).catch(()=>{});
  if(r.status===404||r.status===410){await env.DB.prepare('DELETE FROM mh_push_subs WHERE id=?').bind(sub.id).run();}
  return r.status;
 }catch{return 0;}
}
async function pushFanout(env,{audience,category,title,body,page,id}){
 const keys=await vapidKeys(env);if(!keys)return;
 const subs=await env.DB.prepare('SELECT * FROM mh_push_subs').all();
 for(const sub of subs.results||[]){
  const targeted=audience==='all'||sub.user_key===audience||(audience.startsWith('plex:')&&sub.user_key===audience);
  if(!targeted)continue;
  if(await notifyMuted(env,sub.user_key,category))continue;
  await pushSend(env,keys,sub,{title,body,page,tag:category+':'+id});
 }
}
const SW_JS=`self.addEventListener('push',e=>{let d={};try{d=e.data?e.data.json():{};}catch{}const title=d.title||'ScreenDen';e.waitUntil(self.registration.showNotification(title,{body:d.body||'',tag:d.tag||undefined,data:{page:d.page||''}}));});
self.addEventListener('notificationclick',e=>{e.notification.close();const page=(e.notification.data&&e.notification.data.page)||'';e.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(list=>{for(const c of list){if('focus' in c){if(page)c.postMessage({type:'mh-navigate',page});return c.focus();}}return clients.openWindow('/'+(page?'#'+page:''));}));});
`;
async function setSetting(env,k,v){await env.DB.prepare('CREATE TABLE IF NOT EXISTS mh_dashboard_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)').run();await env.DB.prepare('INSERT INTO mh_dashboard_settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').bind(k,String(v)).run();}
const DISCORD_ADMIN_DEFAULTS=['requests_admin','reports','server'];
const DISCORD_PUBLIC_DEFAULTS=['request','featured','news','movie-night'];
async function discordConfig(env){
 await env.DB.prepare('CREATE TABLE IF NOT EXISTS mh_dashboard_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)').run();
 const keys=['discordWebhookAdmin','discordCatsAdmin','discordLastStatusAdmin','discordLastAtAdmin','discordWebhookPublic','discordCatsPublic','discordLastStatusPublic','discordLastAtPublic','discordWebhook','discordCats','discordLastStatus','discordLastAt'];
 const r=await env.DB.prepare('SELECT key,value FROM mh_dashboard_settings WHERE key IN ('+keys.map(()=>'?').join(',')+')').bind(...keys).all();
 const v=Object.fromEntries((r.results||[]).map(x=>[x.key,x.value]));
 const parse=s=>{try{const c=JSON.parse(s||'null');return Array.isArray(c)?c:null;}catch{return null;}};
 // The single v3.6.36 webhook was the shared channel, so it becomes the
 // public webhook when no public one has been saved yet.
 const hook=(t,legacy)=>v['discordWebhook'+t]!==undefined?v['discordWebhook'+t]:(legacy?v.discordWebhook||'':'');
 const side=t=>({webhook:hook(t,t==='Public'),cats:parse(v['discordCats'+t])||parse(t==='Public'?v.discordCats:null)||(t==='Admin'?DISCORD_ADMIN_DEFAULTS:DISCORD_PUBLIC_DEFAULTS),lastStatus:v['discordLastStatus'+t]||(t==='Public'?v.discordLastStatus||'':''),lastAt:Number(v['discordLastAt'+t]||(t==='Public'?v.discordLastAt:0))||0});
 return {admin:side('Admin'),public:side('Public')};
}
function discordWebhookValid(s){try{const u=new URL(String(s||''));return u.protocol==='https:'&&['discord.com','discordapp.com','canary.discord.com'].includes(u.hostname)&&/^\/api\/webhooks\/\d+\/[\w-]+$/.test(u.pathname);}catch{return false;}}
async function discordPost(env,webhook,title,body,which){
 let status=0;
 try{const r=await fetch(webhook,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({username:'ScreenDen',content:('**'+title+'**'+(body?'\n'+body:'')).slice(0,1900),allowed_mentions:{parse:[]}})});status=r.status;}catch{status=0;}
 const cap=which==='admin'?'Admin':'Public';
 await setSetting(env,'discordLastStatus'+cap,String(status)).catch(()=>{});
 await setSetting(env,'discordLastAt'+cap,String(Date.now())).catch(()=>{});
 return status;
}
// Two Discord channels: admin alerts (new requests, reports, server flips)
// go to the admin webhook; household alerts (request outcomes, picks, news,
// Movie Night) go to the public webhook. Category lists are adjustable per
// channel, and a category may be sent to both.
async function discordFanout(env,{category,title,body}){
 const cfg=await discordConfig(env);
 if(cfg.admin.webhook&&cfg.admin.cats.includes(category))await discordPost(env,cfg.admin.webhook,title,body,'admin');
 if(cfg.public.webhook&&cfg.public.cats.includes(category))await discordPost(env,cfg.public.webhook,title,body,'public');
}
