const MH_DISCOVERY_HTML = "<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>ScreenDen — Discovery</title><link rel=\"stylesheet\" href=\"/styles.css?v=1.0.0-rc.1\"><body><main class=\"discovery-page\"><header class=\"discovery-head\"><a class=\"btn secondary\" href=\"/\">← Back to your dashboard</a><h1>Discover something new.</h1><p class=\"subtle\">Search your next watch, explore upcoming releases, and grow your game library.</p></header><p id=\"status\" role=\"status\"></p><section><h2>Metadata providers</h2><p>Provider settings are managed in <a href=\"/#settings\">Admin Settings → Metadata connections & game library</a>. This page is for metadata search, Coming Soon, and importing games.</p></section><section><h2>Find metadata</h2><select id=\"kind\" aria-label=\"Media type\"><option value=\"game\">Games</option><option value=\"movie\">Movies</option><option value=\"tv\">TV</option></select><select id=\"provider\" aria-label=\"Metadata provider\"><option value=\"steam\">Steam</option><option value=\"rawg\">RAWG</option><option value=\"igdb\">IGDB</option><option value=\"tmdb\">TMDB</option></select><input aria-label=\"Search title\" id=\"query\" placeholder=\"Search title\"><button id=\"search\">Search</button><div id=\"matches\"></div></section><section><h2>Coming Soon</h2><button data-upcoming=\"movie\">Upcoming movies</button><button data-upcoming=\"tv\">Upcoming TV</button><button data-upcoming=\"game\">Upcoming Games</button><div id=\"upcoming\"></div><small>Steam featured upcoming titles or configured RAWG; dates may be unavailable.</small></section><section><h2>Nextcloud → Recently Added Games (admin)</h2><input aria-label=\"Authorized Nextcloud folder path\" id=\"path\" placeholder=\"Folder path within authorized DAV root\"><input aria-label=\"Filter filenames\" id=\"filter\" placeholder=\"Filter filenames\"><button id=\"scan\">Browse games</button><div id=\"pickbar\"></div><div id=\"files\"></div><h3>Recently Added Games</h3><div id=\"recent\"></div></section></main><script src=\"/media-discovery.js\"></script></body></html>";
const MH_DISCOVERY_JS = "const $=x=>document.getElementById(x);const status=(x,bad=false)=>{$('status').textContent=x;$('status').className=bad?'error':''};const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));async function api(url,opts){const r=await fetch(url,{credentials:'same-origin',...opts});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}const post=(url,b)=>api(url,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(b)});const card=(x)=>'<article>'+(x.image?'<img alt=\"\" src=\"'+esc(x.image)+'\">':'')+'<div><b>'+esc(x.title)+'</b> <small>'+esc(x.releaseDate||'')+'</small><p>'+esc((x.description||'').slice(0,250))+'</p>'+(x.url?'<a target=\"_blank\" rel=\"noopener noreferrer\" href=\"'+esc(x.url)+'\">Source ↗</a>':'')+'</div></article>';\n// Selection model (fixed in v3.6.36): picking a search result makes it THE\n// game, shown in a persistent bar above the file list. Each file row then\n// publishes immediately with that game — no staging queue, no second\n// \"publish the staged items\" step, and folder navigation keeps the pick.\nlet selected=null;\nfunction renderPick(){const bar=$('pickbar');if(!bar)return;bar.innerHTML=selected?'<p class=\"pickbar\">Publishing as: <b>'+esc(selected.title)+'</b> <small>('+esc(selected.provider)+')</small> — each file below publishes immediately with this game. <button id=\"pick-clear\" type=\"button\">Clear selection</button></p>':'<p class=\"pickbar pickbar-empty\">No game selected. Search above, choose “Select for publishing” on the right match, then publish files below — one click each.</p>';const c=$('pick-clear');if(c)c.onclick=()=>{selected=null;renderPick();status('Selection cleared')}}\nasync function init(){try{const d=await api('/api/metadata/settings');window.mhProviders=d.providers;$('provider').value=d.providers.game;renderPick();await recent()}catch(e){status(e.message,true)}}\n$('kind').onchange=()=>{$('provider').value=$('kind').value==='game'?(window.mhProviders?.game||'steam'):'tmdb'};\n$('search').onclick=async()=>{try{const kind=$('kind').value,provider=$('provider').value,q=$('query').value;const d=await api('/api/metadata/search?kind='+kind+'&provider='+provider+'&q='+encodeURIComponent(q));$('matches').innerHTML=d.results.map((x,i)=>card(x)+(kind==='game'?'<button data-match=\"'+i+'\">Select for publishing</button>':'')).join('')||'No matches';$('matches').querySelectorAll('[data-match]').forEach(b=>b.onclick=()=>{selected=d.results[+b.dataset.match];renderPick();status('Selected '+selected.title+' — now publish files below with one click each')})}catch(e){status(e.message,true)}};\ndocument.querySelectorAll('[data-upcoming]').forEach(b=>b.onclick=async()=>{try{const d=await api('/api/metadata/coming-soon?kind='+b.dataset.upcoming);$('upcoming').innerHTML=(d.items||[]).map(card).join('')||esc(d.warning||'No upcoming releases found')}catch(e){status(e.message,true)}});\n$('scan').onclick=async()=>{try{const d=await api('/api/admin/games/discover?path='+encodeURIComponent($('path').value)+'&q='+encodeURIComponent($('filter').value));const rows=d.items.map((x,i)=>'<article><div><b>'+esc(x.name)+'</b> <small>→ '+esc(x.suggested)+'</small><p><button data-file=\"'+i+'\">'+(selected?'Publish as '+esc(selected.title):'Publish (select a game first)')+'</button> '+(x.folder?'<button data-folder=\"'+i+'\">Open folder</button>':'')+'</p></div></article>').join('');$('files').innerHTML=rows||'<p>No items in this folder.</p>';$('files').querySelectorAll('[data-folder]').forEach(b=>b.onclick=()=>{$('path').value=d.items[+b.dataset.folder].path;$('scan').click()});$('files').querySelectorAll('[data-file]').forEach(b=>b.onclick=async()=>{const item=d.items[+b.dataset.file];if(!selected){$('kind').value='game';$('kind').onchange();$('query').value=item.suggested;status('Search Steam for “'+item.suggested+'” and choose “Select for publishing” on the right match');window.scrollTo({top:0,behavior:'smooth'});return}b.disabled=true;const old=b.textContent;b.textContent='Publishing…';try{await post('/api/admin/games/publish',{provider:selected.provider,providerId:selected.id,path:item.path});b.textContent='✓ Published to Recently Added Games';status(item.name+' published as '+selected.title);await recent()}catch(err){b.disabled=false;b.textContent=old;status(err.message,true)}})}catch(e){status(e.message,true)}};\nasync function recent(){const d=await api('/api/games/recent');$('recent').innerHTML=d.items.map(x=>card(x)+'<a href=\"'+esc(x.nextcloudUrl)+'\" target=\"_blank\" rel=\"noopener noreferrer\">Open in Nextcloud</a>').join('')||'No published games'}\ninit();\n";

// Personal Nextcloud connections. Every query is scoped to the authenticated member.
function personalNcUrl(value){const u=new URL(String(value||''));const marker=u.pathname.indexOf('/apps/files');if(marker>=0)u.pathname=u.pathname.slice(0,marker).replace(/\/index\.php$/,'');u.search='';u.hash='';return labUrl(u.toString());}
async function personalNcRoute(req,env,u,owner){
 try{
 const action=u.pathname.slice('/api/plex/nextcloud/'.length);
 if(!['GET','POST'].includes(req.method))return err('Method not allowed',405);
 if(req.method==='POST'&&(!adminOrigin(req)||req.headers.get('content-type')?.split(';')[0]!=='application/json'))return err('Invalid origin or content type',403);
 await env.DB.prepare('CREATE TABLE IF NOT EXISTS mh_nc_personal (owner TEXT NOT NULL,id TEXT NOT NULL,name TEXT NOT NULL,url TEXT NOT NULL,username TEXT,password_enc TEXT,flow_enc TEXT,folder TEXT NOT NULL DEFAULT \'\',chosen INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(owner,id))').run();
 let b={};if(req.method==='POST'){const raw=await req.text();if(raw.length>5000)return err('Request too large',413);b=JSON.parse(raw||'{}');}
 await ncAvailableInit(env);await ncEnsureColumn(env,'mh_nc_personal','folder_override','INTEGER NOT NULL DEFAULT 1');
 await env.DB.prepare("CREATE TABLE IF NOT EXISTS mh_nc_private_servers (owner TEXT NOT NULL,id TEXT NOT NULL,name TEXT NOT NULL,url TEXT NOT NULL,start_folder TEXT NOT NULL DEFAULT '',PRIMARY KEY(owner,id))").run();
 await env.DB.prepare('CREATE TABLE IF NOT EXISTS mh_nc_personal_pins (owner TEXT NOT NULL,server_id TEXT NOT NULL,path TEXT NOT NULL,label TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(owner,server_id,path))').run();
 const sharedList=()=>env.DB.prepare('SELECT p.id,a.name,a.url,p.username,CASE WHEN a.allow_custom=1 AND p.folder_override=1 THEN p.folder ELSE a.start_folder END AS folder,p.chosen,a.start_folder,a.allow_custom,p.folder_override FROM mh_nc_personal p JOIN mh_nc_available a ON p.id=a.id WHERE p.owner=? AND a.enabled=1 ORDER BY a.name,a.id').bind(owner).all();
 const privateList=()=>env.DB.prepare('SELECT p.id,a.name,a.url,p.username,CASE WHEN p.folder_override=1 THEN p.folder ELSE a.start_folder END AS folder,p.chosen,a.start_folder,1 AS allow_custom,p.folder_override,1 AS personal FROM mh_nc_personal p JOIN mh_nc_private_servers a ON p.id=a.id AND p.owner=a.owner WHERE p.owner=? ORDER BY a.name,a.id').bind(owner).all();
 const list=async()=>({results:[...((await sharedList()).results||[]).map(x=>({...x,personal:0})),...((await privateList()).results||[])]});
 if(action==='servers'&&req.method==='GET')await env.DB.prepare("INSERT OR IGNORE INTO mh_nc_personal(owner,id,name,url,folder,chosen,folder_override) SELECT owner,id,name,url,'',0,0 FROM mh_nc_private_servers WHERE owner=?").bind(owner).run();
 if(action==='servers'&&req.method==='GET')await env.DB.prepare("INSERT OR IGNORE INTO mh_nc_personal(owner,id,name,url,folder,chosen,folder_override) SELECT ?,id,name,url,'',0,0 FROM mh_nc_available WHERE enabled=1").bind(owner).run();
 if(action==='servers'&&req.method==='GET')return json({servers:(await list()).results,secretConfigured:!!(env.NC_LAB_ENCRYPTION_KEY?.length>=32)});
 if(action==='add'&&req.method==='POST'){
 const own=(await env.DB.prepare('SELECT id,url FROM mh_nc_private_servers WHERE owner=?').bind(owner).all()).results||[];if(own.length>=8)return err('You can add up to eight private servers in this browser',400);
 let url,folder;try{url=personalNcUrl(b.url);folder=ncAdminFolder(new URL(String(b.url)).searchParams.get('dir')||'');}catch{return err('Enter a public HTTPS Nextcloud URL, such as https://cloud.example.com/nextcloud',400);}
 const rows=(await list()).results||[];if([...rows,...own].some(x=>x.url===url))return err('That server is already listed. Choose it from the server menu.',400);
 const name=String(b.name||new URL(url).hostname).trim().slice(0,70);if(!name)return err('Server name required',400);const id=crypto.randomUUID();
 await env.DB.batch([env.DB.prepare('INSERT INTO mh_nc_private_servers(owner,id,name,url,start_folder) VALUES(?,?,?,?,?)').bind(owner,id,name,url,folder),env.DB.prepare('UPDATE mh_nc_personal SET chosen=0 WHERE owner=?').bind(owner),env.DB.prepare('INSERT INTO mh_nc_personal(owner,id,name,url,folder,chosen,folder_override) VALUES(?,?,?,?,?,1,0)').bind(owner,id,name,url,'')]);return json({ok:true,id});
 }
 const id=String(b.id||u.searchParams.get('id')||'');
 const server=await env.DB.prepare('SELECT p.id,p.username,p.password_enc,p.flow_enc,a.name,a.url,a.allow_custom,a.start_folder,CASE WHEN a.allow_custom=1 AND p.folder_override=1 THEN p.folder ELSE a.start_folder END AS folder FROM mh_nc_personal p JOIN mh_nc_available a ON p.id=a.id WHERE p.owner=? AND p.id=? AND a.enabled=1').bind(owner,id).first()||await env.DB.prepare('SELECT p.id,p.username,p.password_enc,p.flow_enc,a.name,a.url,1 AS allow_custom,a.start_folder,CASE WHEN p.folder_override=1 THEN p.folder ELSE a.start_folder END AS folder,1 AS personal FROM mh_nc_personal p JOIN mh_nc_private_servers a ON p.id=a.id AND p.owner=a.owner WHERE p.owner=? AND p.id=?').bind(owner,id).first();if(!server)return err('Unknown personal server',404);
 const update=(field,value)=>env.DB.prepare('UPDATE mh_nc_personal SET '+field+'=? WHERE owner=? AND id=?').bind(value,owner,id).run();
 if(action==='remove-server'&&req.method==='POST'){
 if(!server.personal)return err('Only your private servers can be removed here',403);
 await env.DB.batch([env.DB.prepare('DELETE FROM mh_nc_personal WHERE owner=? AND id=?').bind(owner,id),env.DB.prepare('DELETE FROM mh_nc_private_servers WHERE owner=? AND id=?').bind(owner,id)]);return json({ok:true,notice:'Private server removed from this browser. Revoke its app password in Nextcloud Security settings to invalidate access there.'});
 }
 if(action==='remove'&&req.method==='POST'){await env.DB.prepare('DELETE FROM mh_nc_personal WHERE owner=? AND id=?').bind(owner,id).run();return json({ok:true,notice:'Connection removed. Revoke Tavern access in Nextcloud Security settings to invalidate its app password.'});}
 if(action==='folder-default'&&req.method==='POST'){await update('folder_override',0);return json({ok:true});}
 if(action==='choose'&&req.method==='POST'){await env.DB.batch([env.DB.prepare('UPDATE mh_nc_personal SET chosen=0 WHERE owner=?').bind(owner),env.DB.prepare('UPDATE mh_nc_personal SET chosen=1 WHERE owner=? AND id=?').bind(owner,id)]);return json({ok:true});}
 if(action==='start'&&req.method==='POST'){
 await labKey(env);const r=await labFetch(server.url+'/index.php/login/v2',{method:'POST',headers:{Accept:'application/json','User-Agent':'Tavern Nextcloud widget'}});if(!r.ok)return err('Nextcloud login returned HTTP '+r.status,502);
 const v=await r.json(),login=new URL(v.login),poll=new URL(v.poll?.endpoint);const root=new URL(server.url);
 if(login.origin!==root.origin||poll.origin!==root.origin||login.username||login.password||poll.username||poll.password||!v.poll?.token||String(v.poll.token).length>2000)return err('Unexpected Nextcloud login response',502);
 await update('flow_enc',await labEncrypt(env,JSON.stringify({url:poll.toString(),token:v.poll.token,expires:Date.now()+12*60000})));
 return json({loginUrl:login.toString()});
 }
 if(action==='poll'&&req.method==='POST'){
 if(!server.flow_enc)return err('Start a new login',404);const flow=JSON.parse(await labDecrypt(env,server.flow_enc));if(flow.expires<Date.now()){await update('flow_enc',null);return err('Login expired. Connect again.',410);}
 const r=await labFetch(flow.url,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({token:flow.token}).toString()});if(r.status===404)return json({pending:true});if(!r.ok)return err('Nextcloud authorization failed (HTTP '+r.status+')',502);
 const v=await r.json();if(!v.loginName||!v.appPassword||personalNcUrl(v.server)!==server.url)return err('Nextcloud authorization did not match this server',502);
 const auth='Basic '+btoa(unescape(encodeURIComponent(v.loginName+':'+v.appPassword)));
 // Login Flow may return an email; DAV needs the canonical Nextcloud user ID.
 const who=await labFetch(server.url+'/ocs/v2.php/cloud/user?format=json',{headers:{Authorization:auth,'OCS-APIRequest':'true',Accept:'application/json'}});if(!who.ok)return err('Could not identify your Nextcloud account',502);
 const profile=await who.json(),uid=profile.ocs?.data?.id;if(!uid||profile.ocs?.meta?.status!=='ok')return err('Could not identify your Nextcloud account',502);
 const credentials=await labEncrypt(env,JSON.stringify({login:String(v.loginName),password:String(v.appPassword),uid:String(uid)}));
 await env.DB.prepare('UPDATE mh_nc_personal SET username=?,password_enc=?,flow_enc=NULL WHERE owner=? AND id=?').bind(String(uid).slice(0,200),credentials,owner,id).run();return json({connected:true});
 }
 if(['browse','folder'].includes(action)&&((action==='browse'&&req.method==='GET')||(action==='folder'&&req.method==='POST'))){
 if(action==='folder'&&!server.allow_custom)return err('The administrator manages this server’s starting folder',403);
 if(!server.password_enc)return err('Connect your Nextcloud account first',401);
 const segments=ncSegments(String(action==='folder'?b.path:u.searchParams.get('path')??server.folder));const path=segments.join('/');
 const c=JSON.parse(await labDecrypt(env,server.password_enc));const target=server.url+'/remote.php/dav/files/'+encodeURIComponent(c.uid)+'/'+segments.map(encodeURIComponent).join('/')+(segments.length?'/':'');
 const r=await labFetch(target,{method:'PROPFIND',headers:{Authorization:'Basic '+btoa(unescape(encodeURIComponent(c.login+':'+c.password))),Depth:'1','Content-Type':'application/xml'},body:'<?xml version="1.0"?><d:propfind xmlns:d="DAV:"><d:allprop/></d:propfind>'});
 if(r.status!==207)return err(r.status===401?'Nextcloud access expired. Reconnect your account.':'Could not open folder (Nextcloud HTTP '+r.status+')',502);
 const xml=await r.text();if(xml.length>4000000)return err('This folder is too large to list',502);const parsed=labDavEntries(xml,target);if(!/<(?:[\w-]+:)?collection\s*\/?\s*>/i.test(xml))return err('Choose a folder, rather than a file',400);
 if(action==='folder')await env.DB.prepare('UPDATE mh_nc_personal SET folder=?,folder_override=1 WHERE owner=? AND id=?').bind(path,owner,id).run();
 return json({path,items:parsed.items.slice(0,200).map(x=>({...x,path:[...segments,x.name].join('/')})),partial:parsed.items.length>200,openUrl:server.url+'/index.php/apps/files/?dir='+encodeURIComponent('/'+path)});
 }
 if(action==='pins'&&req.method==='GET'){
  const p=await env.DB.prepare('SELECT path,label FROM mh_nc_personal_pins WHERE owner=? AND server_id=? ORDER BY created_at').bind(owner,id).all();
  return json({pins:p.results||[]});
 }
 if(action==='pin'&&req.method==='POST'){
  if(!server.password_enc)return err('Connect your Nextcloud account first',401);
  const segments=ncSegments(String(b.path||''));const path=segments.join('/');
  const c=JSON.parse(await labDecrypt(env,server.password_enc));const target=server.url+'/remote.php/dav/files/'+encodeURIComponent(c.uid)+'/'+segments.map(encodeURIComponent).join('/')+(segments.length?'/':'');
  const r=await labFetch(target,{method:'PROPFIND',headers:{Authorization:'Basic '+btoa(unescape(encodeURIComponent(c.login+':'+c.password))),Depth:'0','Content-Type':'application/xml'},body:'<?xml version="1.0"?><d:propfind xmlns:d="DAV:"><d:prop><d:resourcetype/></d:prop></d:propfind>'});
  if(r.status!==207)return err('Could not pin that folder (Nextcloud HTTP '+r.status+')',502);
  const xml=await r.text();if(!/<(?:[\w-]+:)?collection\s*\/?\s*>/i.test(xml))return err('Only folders can be pinned as favourites',400);
  const label=String(b.label||segments[segments.length-1]||'All files').trim().slice(0,100)||'All files';
  await env.DB.prepare('INSERT OR REPLACE INTO mh_nc_personal_pins(owner,server_id,path,label,created_at) VALUES(?,?,?,?,?)').bind(owner,id,path,label,new Date().toISOString()).run();return json({ok:true});
 }
 if(action==='unpin'&&req.method==='POST'){
  const path=ncSegments(String(b.path||'')).join('/');
  await env.DB.prepare('DELETE FROM mh_nc_personal_pins WHERE owner=? AND server_id=? AND path=?').bind(owner,id,path).run();return json({ok:true});
 }
 if(action==='search'&&req.method==='GET'){
  if(!server.password_enc)return err('Connect your Nextcloud account first',401);
  const q=String(u.searchParams.get('q')||'').trim().slice(0,80);if(q.length<2)return err('Search needs at least two characters',400);
  const c=JSON.parse(await labDecrypt(env,server.password_enc));const auth='Basic '+btoa(unescape(encodeURIComponent(c.login+':'+c.password)));
  // Bounded breadth-first walk from the member's starting folder: at most 40
  // folders listed, at most 4 levels below the start, at most 60 results.
  // Unreadable folders are skipped, never fatal.
  const start=ncSegments(String(server.folder||''));const needle=q.toLowerCase();const results=[];const queue=[start];let visited=0;
  while(queue.length&&visited<40&&results.length<60){
   const segs=queue.shift();visited++;
   const target=server.url+'/remote.php/dav/files/'+encodeURIComponent(c.uid)+'/'+segs.map(encodeURIComponent).join('/')+(segs.length?'/':'');
   let entries=[];try{const r=await labFetch(target,{method:'PROPFIND',headers:{Authorization:auth,Depth:'1','Content-Type':'application/xml'},body:'<?xml version="1.0"?><d:propfind xmlns:d="DAV:"><d:allprop/></d:propfind>'});if(r.status!==207)continue;const xml=await r.text();if(xml.length>4000000)continue;entries=labDavEntries(xml,target).items;}catch{continue}
   for(const e of entries){const p=[...segs,e.name];if(e.name.toLowerCase().includes(needle))results.push({name:e.name,folder:e.folder,size:e.size,path:p.join('/')});if(e.folder&&segs.length<start.length+4&&queue.length<80)queue.push(p);}
  }
  return json({query:q,server:server.name,results:results.slice(0,60),truncated:queue.length>0||results.length>=60});
 }
 return err('Not found',404);
 }catch(e){return err(e?.name==='AbortError'?'Nextcloud took too long to respond. Try again.':'Unable to complete Nextcloud request. Check the server URL and connection, then retry.',400);}
}



async function ncEnsureColumn(env,table,name,definition){const columns=(await env.DB.prepare('PRAGMA table_info('+table+')').all()).results||[];if(columns.some(x=>x.name===name))return;try{await env.DB.prepare('ALTER TABLE '+table+' ADD COLUMN '+name+' '+definition).run()}catch(e){if(!((await env.DB.prepare('PRAGMA table_info('+table+')').all()).results||[]).some(x=>x.name===name))throw e;}}
async function ncAvailableInit(env){await env.DB.prepare('CREATE TABLE IF NOT EXISTS mh_nc_available (id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1)').run();await ncEnsureColumn(env,'mh_nc_available','start_folder',"TEXT NOT NULL DEFAULT ''");await ncEnsureColumn(env,'mh_nc_available','allow_custom','INTEGER NOT NULL DEFAULT 1');}
function ncAdminFolder(value){return ncSegments(String(value||'').trim().replace(/^\/+|\/+$/g,'')).join('/');}
async function ncAvailableRoute(req,env){
 if(!await adminSession(req,env))return err('Admin authorization required',403);
 try{await ncAvailableInit(env);if(req.method==='GET')return json({servers:(await env.DB.prepare('SELECT * FROM mh_nc_available ORDER BY name,id').all()).results});
 if(req.method!=='POST'||!adminOrigin(req)||req.headers.get('content-type')?.split(';')[0]!=='application/json')return err('Invalid request',403);
 const raw=await req.text();if(raw.length>5000)return err('Request too large',413);const b=JSON.parse(raw);
 if(['add','save'].includes(b.action)){
 const name=String(b.name||'').trim().slice(0,70),folder=ncAdminFolder(b.startFolder),allow=b.allowCustom!==false?1:0;if(!name)return err('Name required',400);
 if(b.action==='save'){if(typeof b.enabled!=='boolean'||typeof b.allowCustom!=='boolean')return err('Invalid server settings',400);const found=await env.DB.prepare('SELECT id FROM mh_nc_available WHERE id=?').bind(String(b.id)).first();if(!found)return err('Unknown server',404);await env.DB.prepare('UPDATE mh_nc_available SET name=?,start_folder=?,allow_custom=?,enabled=? WHERE id=?').bind(name,folder,allow,b.enabled?1:0,String(b.id)).run();return json({ok:true});}
 const url=personalNcUrl(b.url),list=(await env.DB.prepare('SELECT * FROM mh_nc_available').all()).results||[];if(list.length>=8||list.some(x=>x.url===url))return err('Server already exists or eight-server limit reached',400);
 await env.DB.prepare('INSERT INTO mh_nc_available(id,name,url,enabled,start_folder,allow_custom) VALUES(?,?,?,1,?,?)').bind(crypto.randomUUID(),name,url,folder,allow).run();return json({ok:true});
 }
 if(b.action==='visibility'&&typeof b.enabled==='boolean'){await env.DB.prepare('UPDATE mh_nc_available SET enabled=? WHERE id=?').bind(b.enabled?1:0,String(b.id)).run();return json({ok:true});}
 return err('Invalid action',400);
 }catch{return err('Check the server name, public HTTPS URL and folder path (for example /Archive)',400);}
}

async function ncPersonalBrowserRoute(req,env,u){
 // This identity is independent of Plex and carries no Nextcloud credentials.
 let sid=/(?:^|;\s*)mh_nc_browser=([a-f0-9]{64})(?:;|$)/.exec(req.headers.get('cookie')||'')?.[1];const fresh=!sid;if(!sid)sid=randomId();
 const response=await personalNcRoute(req,env,u,await hash(sid));
 if(fresh){const headers=new Headers(response.headers);headers.append('Set-Cookie','mh_nc_browser='+sid+'; Path=/api/plex/nextcloud; HttpOnly; Secure; SameSite=Lax; Max-Age=2592000');return new Response(response.body,{status:response.status,headers});}return response;
}

const FTP_GUIDE_HTML="<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta charset=\"utf-8\">\n<title>How to Get Files from the Shared Folder — Cyberduck Guide</title>\n<style>\n  :root{\n    --ink:#1c2733; --blue:#1463b4; --blue-dark:#0d4c8c; --green:#1d7a3a; --green-bg:#e8f6ec;\n    --red:#c0272d; --red-bg:#fdecec; --amber:#8a5a00; --amber-bg:#fff6dd; --grey-bg:#f2f5f8;\n    --line:#c9d4de; --radius:14px;\n  }\n  *{box-sizing:border-box}\n  html{font-size:17px}\n  body{margin:0;font-family:\"Segoe UI\",Arial,Helvetica,sans-serif;color:var(--ink);line-height:1.5;background:#fff}\n  .page{max-width:820px;margin:0 auto;padding:28px 34px 20px}\n  h1{font-size:2rem;line-height:1.2;margin:0 0 6px;color:var(--blue-dark)}\n  h2{font-size:1.45rem;margin:0 0 10px;color:var(--blue-dark);display:flex;align-items:center;gap:12px}\n  h3{font-size:1.12rem;margin:16px 0 6px}\n  p{margin:8px 0}\n  .subtitle{font-size:1.15rem;color:#44566b;margin:0 0 14px}\n  .stepnum{flex:0 0 auto;width:46px;height:46px;border-radius:50%;background:var(--blue);color:#fff;\n    font-size:1.5rem;font-weight:700;display:flex;align-items:center;justify-content:center}\n  section{border-top:3px solid var(--grey-bg);padding:22px 0 8px;margin-top:14px}\n  ol.big, ul.big{margin:8px 0 8px 4px;padding-left:26px}\n  ol.big li, ul.big li{margin:7px 0}\n  .callout{border-radius:var(--radius);padding:14px 18px;margin:14px 0;font-size:1.02rem}\n  .ok{background:var(--green-bg);border:2px solid var(--green)}\n  .warn{background:var(--red-bg);border:2px solid var(--red)}\n  .tip{background:var(--amber-bg);border:2px solid #d9a400}\n  .info{background:var(--grey-bg);border:2px solid var(--line)}\n  .callout .ctitle{font-weight:700;display:block;margin-bottom:2px}\n  .creds{background:#eef5fd;border:2.5px dashed var(--blue);border-radius:var(--radius);padding:16px 20px;margin:16px 0}\n  .creds table{border-collapse:collapse;width:100%;font-size:1.08rem}\n  .creds td{padding:6px 8px;vertical-align:top}\n  .creds td.k{font-weight:700;width:32%;color:var(--blue-dark)}\n  .fill{border-bottom:2px solid #7d8ea0;min-width:200px;display:inline-block;height:1.2em}\n  code,.mono{font-family:Consolas,\"Courier New\",monospace;background:#e8eef4;padding:1px 7px;border-radius:6px;font-size:1.02em;font-weight:600}\n  .two{display:flex;gap:16px;flex-wrap:wrap}\n  .two > div{flex:1 1 300px;background:var(--grey-bg);border:2px solid var(--line);border-radius:var(--radius);padding:6px 18px 12px}\n  /* ------- mock UI illustrations ------- */\n  .illus{margin:16px 0}\n  .illus .cap{font-size:.92rem;color:#5a6b7d;text-align:center;margin-top:6px;font-style:italic}\n  .win{border:2px solid #8fa3b5;border-radius:10px;overflow:hidden;background:#fff;box-shadow:0 3px 10px rgba(30,50,70,.12);max-width:640px;margin:0 auto}\n  .winbar{background:linear-gradient(#dfe9f2,#c8d8e6);padding:7px 12px;font-weight:700;font-size:.95rem;display:flex;align-items:center;gap:8px;color:#24344a}\n  .dots span{display:inline-block;width:12px;height:12px;border-radius:50%;margin-right:4px}\n  .toolbar{background:#eef3f7;padding:10px 12px;border-bottom:1.5px solid var(--line);display:flex;gap:10px;align-items:center;flex-wrap:wrap}\n  .tbtn{border:1.5px solid #7d93a8;background:#fff;border-radius:8px;padding:8px 14px;font-size:.98rem;font-weight:600;color:#24344a}\n  .tbtn.dim{color:#8496a7;font-weight:400}\n  .hl{outline:4px solid var(--red);outline-offset:2px;position:relative}\n  .dlg{padding:16px 20px 18px}\n  .dlg label{display:block;font-size:.92rem;font-weight:700;color:#43576c;margin:10px 0 3px}\n  .field{border:1.5px solid #93a8bb;border-radius:7px;padding:9px 11px;font-size:1.02rem;background:#fff}\n  .field.sel{background:#eef5fd;border-color:var(--blue)}\n  .rowflex{display:flex;gap:12px}.rowflex>div{flex:1}\n  .rowflex .port{flex:0 0 110px}\n  .bigbtn{display:inline-block;background:var(--blue);color:#fff;font-weight:700;border-radius:9px;padding:12px 30px;font-size:1.1rem;margin-top:16px}\n  .callnum{display:inline-flex;width:30px;height:30px;border-radius:50%;background:var(--red);color:#fff;font-weight:800;\n    align-items:center;justify-content:center;font-size:1rem;vertical-align:middle;margin-right:6px}\n  .legend{max-width:640px;margin:10px auto 0;font-size:1rem}\n  .legend li{margin:6px 0}\n  .certbody{padding:18px 22px;text-align:left}\n  .certicon{font-size:2.4rem;float:left;margin-right:14px}\n  .btnrow{display:flex;gap:10px;justify-content:flex-end;padding:0 20px 18px;flex-wrap:wrap}\n  .btn{border:1.5px solid #7d93a8;background:#f4f7fa;border-radius:8px;padding:10px 18px;font-weight:600;font-size:1rem;color:#24344a}\n  .btn.primary{background:var(--blue);color:#fff;border-color:var(--blue)}\n  .filelist{padding:6px 0}\n  .frow{display:flex;gap:10px;align-items:center;padding:9px 16px;border-bottom:1px solid #e3eaf0;font-size:1.02rem}\n  .frow.selrow{background:#dcecfb;font-weight:700}\n  .dragwrap{display:flex;align-items:center;gap:8px;max-width:700px;margin:0 auto}\n  .dragwrap .win{flex:1}\n  .arrow{font-size:2.6rem;color:var(--red);font-weight:900;text-align:center;line-height:1}\n  .desktop{flex:0 0 150px;text-align:center}\n  .deskicon{font-size:4rem;line-height:1.1}\n  .progress{height:22px;border:1.5px solid #7d93a8;border-radius:11px;overflow:hidden;background:#fff}\n  .progress>div{height:100%;width:72%;background:var(--green)}\n  .menu-mock{background:#fff;border:2px solid #8fa3b5;border-radius:8px;max-width:340px;padding:6px 0;box-shadow:0 3px 10px rgba(30,50,70,.15)}\n  .menu-mock div{padding:8px 16px;font-size:1.02rem}\n  .menu-mock .mi-hl{background:#dcecfb;font-weight:700}\n  .chk{display:inline-flex;width:26px;height:26px;border:2.5px solid var(--blue);border-radius:6px;background:#eef5fd;color:var(--blue);font-weight:900;align-items:center;justify-content:center;vertical-align:middle;margin-right:8px}\n  .prefside{display:flex;gap:8px;flex-wrap:wrap;padding:10px 12px;background:#eef3f7;border-bottom:1.5px solid var(--line)}\n  .ptab{border:1.5px solid #7d93a8;background:#fff;border-radius:8px;padding:6px 12px;font-size:.95rem;color:#43576c}\n  .ptab.on{background:var(--blue);color:#fff;border-color:var(--blue);font-weight:700}\n  .pieces{display:flex;align-items:center;gap:10px;max-width:700px;margin:0 auto;flex-wrap:wrap;justify-content:center}\n  .piecebox{border:2px solid var(--blue);background:#eef5fd;border-radius:10px;padding:10px 12px;font-weight:700;text-align:center;font-size:.98rem}\n  .piecebox.small{border-color:#7d93a8;background:#fff;font-size:.92rem;padding:8px 10px}\n  .checklist li{margin:9px 0}\n  .footer{margin-top:26px;border-top:2px solid var(--line);padding-top:10px;font-size:.9rem;color:#5a6b7d;text-align:center}\n  @media print{\n    html{font-size:16.5px}\n    .page{max-width:none;padding:10px 8px}\n    section{break-inside:avoid}\n    .illus,.callout,.creds{break-inside:avoid}\n    .newpage{break-before:page}\n    a{color:var(--ink);text-decoration:none}\n  }\n  @page{size:A4;margin:14mm 13mm}\n</style>\n<style>.mh-guide-header{background:#171923;color:#f4f3ff;padding:20px max(20px,calc((100vw - 900px)/2));display:flex;gap:20px;justify-content:space-between;align-items:center;flex-wrap:wrap}.mh-guide-header>div{display:grid;gap:10px}.mh-guide-header strong{font-size:22px}.mh-guide-header a{color:#d7c8ff;text-decoration:none}.mh-guide-back{font-size:14px}.mh-guide-header nav{display:flex;gap:10px;flex-wrap:wrap}.mh-guide-header nav a{border:1px solid #524763;border-radius:9px;padding:10px 14px;font-size:14px}.mh-guide-contents{max-width:820px;margin:22px auto 0;padding:18px 24px;background:#f2f5f8;border:1px solid #c9d4de;border-radius:12px}.mh-guide-contents summary{font-weight:700;cursor:pointer}.mh-guide-contents nav{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 20px;margin-top:14px}.mh-guide-contents a{color:#0d4c8c;font-size:15px;text-decoration:none}.mh-guide-contents a:hover{text-decoration:underline}.page a{color:#1463b4}.page section{scroll-margin-top:20px}.mh-guide-build{max-width:820px;margin:20px auto;padding:18px 24px;border-top:1px solid #c9d4de;font-size:14px;color:#526074;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}.mh-guide-build a{color:#0d4c8c}.rowflex>div{min-width:0}.fill{max-width:100%}@media(max-width:620px){.page{padding:24px 18px}.mh-guide-contents{margin:16px 14px 0;padding:16px}.mh-guide-contents nav{grid-template-columns:1fr}.mh-guide-header{padding:20px}.rowflex{flex-wrap:wrap}.rowflex>div{flex:1 1 160px}.rowflex .port{flex:0 0 110px}.fill{min-width:100px}.creds{padding:14px}.creds table{font-size:1rem}.creds td{padding:6px 3px}.dlg{padding:14px}.winbar,.field{overflow-wrap:anywhere}.page h1{font-size:1.7rem}.page h2{font-size:1.25rem}}@media print{.mh-guide-header,.mh-guide-contents,.mh-guide-build{display:none}}</style></head>\n<body><header class=\"mh-guide-header\"><div><a class=\"mh-guide-back\" href=\"/#shared-files\">← Shared Files</a><strong>FTP connection guide</strong></div><nav aria-label=\"Guide actions\"><a href=\"https://cyberduck.io/\" target=\"_blank\" rel=\"noopener noreferrer\">Get Cyberduck ↗</a></nav></header><details class=\"mh-guide-contents\" open><summary>In this guide</summary><nav aria-label=\"Guide sections\"><a href=\"#guide-step-1\">1 What is this?</a><a href=\"#guide-step-2\">2 Get Cyberduck (free)</a><a href=\"#guide-step-3\">3 Connect for the first time</a><a href=\"#guide-step-4\">😲 &nbsp;The scary popup — just click Continue</a><a href=\"#guide-step-5\">4 Save it, so next time it's ONE double-click</a><a href=\"#guide-step-6\">5 Turn ON the big-file speed-up (do this once)</a><a href=\"#guide-step-7\">6 Download a file (copy it to your computer)</a><a href=\"#guide-step-8\">7 Where did my file go?</a><a href=\"#guide-step-9\">8 The rules (please read — they are short)</a><a href=\"#guide-step-10\">9 Something went wrong?</a></nav></details>\n<div class=\"page\">\n\n  <h1>📥 How to Get Files from the Shared Folder</h1>\n  <p class=\"subtitle\">A step-by-step guide with pictures. Take it slow — you only set this up once.</p>\n\n  <div class=\"creds\">\n    <p style=\"margin-top:0;font-size:1.15rem\"><strong>✍️ YOUR LOGIN DETAILS — this is the most important box in the guide</strong></p>\n    <p style=\"margin-top:0\">The person who gave you this guide filled this box in before sending it to you. Everybody the folder is shared with uses this <strong>same</strong> login. You will need it in Step 3 — this box is where you look it up, every time.</p>\n    <table>\n      <tr><td class=\"k\">Server</td><td><span class=\"mono\">your-server.example.com</span></td></tr>\n      <tr><td class=\"k\">Port</td><td><span class=\"mono\">21</span></td></tr>\n      <tr><td class=\"k\">Username</td><td><span class=\"fill\">&nbsp;</span></td></tr>\n      <tr><td class=\"k\">Password</td><td><span class=\"fill\">&nbsp;</span></td></tr>\n    </table>\n    <p style=\"margin-bottom:0\">Do not pass this login on to anyone else. If someone else needs it, tell the person who gave you this guide — they decide who gets it.</p>\n  </div>\n\n  <section id=\"guide-step-1\">\n    <h2><span class=\"stepnum\">1</span> What is this?</h2>\n    <p>There is a private folder on the internet with files in it, and it is being shared with you.</p>\n    <p>To get the files, you use a free program called <strong>Cyberduck</strong>. Think of Cyberduck as a window that lets you look into that folder and copy files to your own computer.</p>\n    <p>That is all it does. You are not installing anything strange, and nobody else can see your computer.</p>\n  </section>\n\n  <section id=\"guide-step-2\">\n    <h2><span class=\"stepnum\">2</span> Get Cyberduck (free)</h2>\n    <ol class=\"big\">\n      <li>Open your web browser (Chrome, Edge, Safari — any of them).</li>\n      <li>Type this address exactly: <code><a href=\"https://cyberduck.io/\" target=\"_blank\" rel=\"noopener noreferrer\">cyberduck.io</a></code> and press <strong>Enter</strong>.</li>\n      <li>Click the big <strong>Download</strong> button on that page.</li>\n      <li>Open the file that downloads, and follow the install steps.</li>\n    </ol>\n    <div style=\"background:var(--grey-bg);border:2px solid var(--line);border-radius:14px;padding:6px 18px 12px\">\n      <h3>🪟 On Windows (this is what this guide is written for)</h3>\n      <p>Click <strong>Download Cyberduck for Windows</strong>. Open the downloaded file and click <strong>Next</strong> a few times, then <strong>Finish</strong>. You will find Cyberduck in your <strong>Start menu</strong>.</p>\n      <p style=\"color:#5a6b7d\">🍎 On a Mac instead? Download the Mac version, open it, and drag the Cyberduck duck picture into the Applications folder. Everything after that works the same — except one thing in Step 5: on a Mac, Preferences is under the <strong>Cyberduck</strong> menu, not the Edit menu.</p>\n    </div>\n    <div class=\"callout warn\"><span class=\"ctitle\">⚠️ Only download from <a href=\"https://cyberduck.io/\" target=\"_blank\" rel=\"noopener noreferrer\">cyberduck.io</a></span>\n    Do not get Cyberduck from any other website. Other sites can add junk. If the page does not say <strong><a href=\"https://cyberduck.io/\" target=\"_blank\" rel=\"noopener noreferrer\">cyberduck.io</a></strong> at the top, close it.</div>\n    <div class=\"callout tip\"><span class=\"ctitle\">💡 A note about paying</span>\n    Cyberduck is free. If it ever asks for a donation, you can say no and keep using it.</div>\n  </section>\n\n  <section class=\"newpage\" id=\"guide-step-3\">\n    <h2><span class=\"stepnum\">3</span> Connect for the first time</h2>\n    <ol class=\"big\">\n      <li>Open <strong>Cyberduck</strong>.</li>\n      <li>Click the <strong>Open Connection</strong> button at the top left.</li>\n      <li>A box opens. Fill it in exactly like the picture below.</li>\n      <li>Click the big blue <strong>Connect</strong> button.</li>\n    </ol>\n\n    <div class=\"illus\">\n      <div class=\"win\">\n        <div class=\"winbar\"><span class=\"dots\"><span style=\"background:#e0655f\"></span><span style=\"background:#e8b84b\"></span><span style=\"background:#5cb85c\"></span></span> Cyberduck — Open Connection</div>\n        <div class=\"dlg\">\n          <label><span class=\"callnum\">1</span> Top box — pick this one:</label>\n          <div class=\"field sel\">FTP-SSL (Explicit AUTH TLS) &nbsp;▾</div>\n          <div class=\"rowflex\">\n            <div>\n              <label><span class=\"callnum\">2</span> Server:</label>\n              <div class=\"field\">your-server.example.com</div>\n            </div>\n            <div class=\"port\">\n              <label><span class=\"callnum\">3</span> Port:</label>\n              <div class=\"field\">21</div>\n            </div>\n          </div>\n          <label><span class=\"callnum\">4</span> Username:</label>\n          <div class=\"field\">USERNAME &nbsp;<span style=\"color:#7d8ea0\">(from the box on page 1)</span></div>\n          <label><span class=\"callnum\">5</span> Password:</label>\n          <div class=\"field\">•••••••••• &nbsp;<span style=\"color:#7d8ea0\">(from the box on page 1)</span></div>\n          <span class=\"bigbtn hl\">Connect</span>\n        </div>\n      </div>\n      <p class=\"cap\">Illustration — a drawing of the Cyberduck “Open Connection” box, filled in the way yours should look.</p>\n      <ul class=\"legend\">\n        <li><span class=\"callnum\">1</span> The top box <strong>must</strong> say <strong>FTP-SSL (Explicit AUTH TLS)</strong>. If it just says “FTP”, click it and pick the FTP-SSL one from the list.</li>\n        <li><span class=\"callnum\">2</span> Server: type <code>your-server.example.com</code> — no spaces, nothing before or after it.</li>\n        <li><span class=\"callnum\">3</span> Port: if it does not already say <strong>21</strong>, delete what is there and type <strong>21</strong>.</li>\n        <li><span class=\"callnum\">4</span> + <span class=\"callnum\">5</span> Type the username and password <strong>from the box on page 1</strong> of this guide.</li>\n      </ul>\n    </div>\n  </section>\n\n  <section id=\"guide-step-4\">\n    <h2 style=\"color:var(--red)\">😲 &nbsp;The scary popup — just click Continue</h2>\n    <p>The first time you connect, a box pops up about a <strong>certificate</strong>. <strong>This is normal. It will happen. Do not panic.</strong></p>\n    <p>A “certificate” is just the folder's ID card. Your computer is saying “I have not seen this ID card before.” Because this is a private folder, its ID card is home-made, so your computer complains. It is safe to continue.</p>\n\n    <div class=\"illus\">\n      <div class=\"win\" style=\"max-width:560px\">\n        <div class=\"winbar\">Verify Certificate</div>\n        <div class=\"certbody\">\n          <div class=\"certicon\">⚠️</div>\n          <p style=\"margin-top:0\"><strong>This certificate is not valid.</strong></p>\n          <p>The certificate for <span class=\"mono\">your-server.example.com</span> is not trusted. Do you want to continue anyway?</p>\n          <div style=\"clear:both\"></div>\n        </div>\n        <div class=\"btnrow\">\n          <span class=\"btn\">Disconnect</span>\n          <span class=\"btn\">Show Certificate</span>\n          <span class=\"btn primary hl\">Continue &nbsp;👈 CLICK THIS</span>\n        </div>\n      </div>\n      <p class=\"cap\">Illustration — a drawing of the certificate popup. Click <strong>Continue</strong>. If there is a little box that says “Always trust”, tick it first — then the popup will stop appearing.</p>\n    </div>\n\n    <div class=\"callout ok\"><span class=\"ctitle\">✅ You are in!</span>\n    After you click Continue, you will see a list of files. That list is the inside of the shared folder. You did it.</div>\n  </section>\n\n  <section class=\"newpage\" id=\"guide-step-5\">\n    <h2><span class=\"stepnum\">4</span> Save it, so next time it's ONE double-click</h2>\n    <p>Do this once, right after your first successful connect. It saves everything, so you never have to type it all again.</p>\n    <ol class=\"big\">\n      <li>At the very top of the screen, click the <strong>Bookmark</strong> menu.</li>\n      <li>Click <strong>New Bookmark</strong>.</li>\n      <li>A box opens, already filled in with the same details. You can give it a friendly name at the top, like <strong>Shared Folder</strong>.</li>\n      <li>Close that box (click the ✕ in its corner). You are done — it saves by itself.</li>\n    </ol>\n    <div class=\"illus\">\n      <div class=\"menu-mock\" style=\"margin:0 auto\">\n        <div style=\"color:#7d8ea0;font-size:.9rem;padding-bottom:2px\">— the Bookmark menu —</div>\n        <div class=\"mi-hl\">New Bookmark &nbsp;👈 click this</div>\n        <div>Toggle Bookmarks</div>\n        <div>Edit Bookmark</div>\n      </div>\n      <p class=\"cap\">Illustration — a drawing of the Bookmark menu.</p>\n    </div>\n    <div class=\"callout info\"><span class=\"ctitle\">📌 Next time</span>\n    Open Cyberduck. You will see your saved bookmark in the list. <strong>Double-click it.</strong> Wait a few seconds. You are in. (You may still be asked for the password — type the one from the box on page 1 and click Login.)</div>\n  </section>\n\n  <section class=\"newpage\" id=\"guide-step-6\">\n    <h2><span class=\"stepnum\">5</span> Turn ON the big-file speed-up (do this once)</h2>\n    <p>The files in the shared folder are <strong>big</strong>. Cyberduck has a setting that makes big files download <strong>in pieces, all at the same time</strong>, instead of one slow stream. It is much faster.</p>\n    <p><strong>Turn it on once. Then forget it — it stays on forever.</strong></p>\n    <ol class=\"big\">\n      <li>At the top of Cyberduck, click the <strong>Edit</strong> menu.</li>\n      <li>Click <strong>Preferences…</strong> (a settings window opens).</li>\n      <li>At the top of that window, click <strong>Transfers</strong>.</li>\n      <li>Click the <strong>General</strong> tab (if it is not already showing).</li>\n      <li>Find the heading <strong>Downloads</strong>. Tick this box:<br>\n        <span class=\"chk\">✓</span><strong>Segmented download with multiple connections for file</strong></li>\n      <li>Close the settings window (click the ✕ in its corner). Done.</li>\n    </ol>\n\n    <div class=\"illus\">\n      <div class=\"win\">\n        <div class=\"winbar\">Preferences &nbsp;<span style=\"font-weight:400;color:#5a6b7d\">(Edit menu → Preferences…)</span></div>\n        <div class=\"prefside\">\n          <span class=\"ptab\">General</span><span class=\"ptab\">Browser</span><span class=\"ptab on\"><span class=\"callnum\" style=\"width:24px;height:24px;font-size:.85rem\">1</span>Transfers</span><span class=\"ptab\">Bookmarks</span><span class=\"ptab\">Profiles</span>\n        </div>\n        <div class=\"dlg\">\n          <p style=\"margin:0 0 4px;color:#43576c\"><strong>Tabs:</strong> &nbsp; <u>General</u> &nbsp;·&nbsp; Bandwidth &nbsp;·&nbsp; FTP</p>\n          <label style=\"margin-top:14px\">Downloads</label>\n          <div class=\"field sel\"><span class=\"chk\">✓</span><strong><span class=\"callnum\">2</span>Segmented download with multiple connections for file</strong></div>\n          <div class=\"field\" style=\"margin-top:8px\"><span class=\"chk\" style=\"border-color:#b7c5d1;color:#b7c5d1;background:#fff\">&nbsp;</span><span style=\"color:#7d8ea0\">Other settings — leave these alone</span></div>\n        </div>\n      </div>\n      <p class=\"cap\">Illustration — a drawing of the Preferences window. Click <strong>Transfers</strong> (1), then tick the segmented download box (2).</p>\n    </div>\n\n    <h3>🧩 What it does, in plain English</h3>\n    <div class=\"illus\">\n      <div class=\"pieces\">\n        <div class=\"piecebox\">🎬 One big file</div>\n        <div class=\"arrow\" style=\"font-size:2rem\">➜</div>\n        <div>\n          <div class=\"piecebox small\">Piece 1 ⬇️</div>\n          <div class=\"piecebox small\" style=\"margin-top:5px\">Piece 2 ⬇️</div>\n          <div class=\"piecebox small\" style=\"margin-top:5px\">Piece 3 ⬇️</div>\n          <div class=\"piecebox small\" style=\"margin-top:5px\">Piece 4 ⬇️</div>\n        </div>\n        <div class=\"arrow\" style=\"font-size:2rem\">➜</div>\n        <div class=\"piecebox\">🎬 One big file<br><span style=\"font-weight:400;font-size:.9rem\">put back together for you</span></div>\n      </div>\n      <p class=\"cap\">Illustration — Cyberduck chops a big file into pieces, downloads all the pieces at once, then sticks them back together. You do nothing — it is automatic. It works on files bigger than 100 MB (most of the files in there are).</p>\n    </div>\n\n    <div class=\"callout warn\"><span class=\"ctitle\">⏳ The end of a big download can look “stuck” — it is not</span>\n    After all the pieces arrive, Cyberduck has to <strong>stick them back together</strong> (this is called “merging”). For a very big file that can take a while, and it may look like nothing is happening. <strong>Do NOT cancel. Do NOT close Cyberduck.</strong> Just wait — the finished file appears when the merging is done.</div>\n    <div class=\"callout tip\"><span class=\"ctitle\">💡 If a download fails halfway</span>\n    Do <strong>not</strong> start it again from the beginning — you will waste all the pieces you already have. Open the <strong>Transfers</strong> window, click the failed download once, and click <strong>Resume</strong>. Cyberduck will fetch only the missing pieces.</div>\n  </section>\n\n  <section id=\"guide-step-7\">\n    <h2><span class=\"stepnum\">6</span> Download a file (copy it to your computer)</h2>\n    <p>When you are connected, you see the files from the shared folder in the Cyberduck window. Those files are <strong>not</strong> on your computer yet. You have to copy the ones you want.</p>\n    <p><strong>The easy way — drag it:</strong></p>\n    <ol class=\"big\">\n      <li>Find the file (or folder) you want.</li>\n      <li>Click it once to highlight it.</li>\n      <li>Hold the mouse button down and <strong>drag it onto your Desktop</strong> — or onto any folder on your computer — then let go.</li>\n    </ol>\n    <div class=\"illus\">\n      <div class=\"dragwrap\">\n        <div class=\"win\">\n          <div class=\"winbar\">your-server.example.com</div>\n          <div class=\"filelist\">\n            <div class=\"frow\">📁 &nbsp;Movies</div>\n            <div class=\"frow selrow\">🎬 &nbsp;My-Big-Video.mp4 &nbsp;👈 drag this</div>\n            <div class=\"frow\">📄 &nbsp;notes.txt</div>\n          </div>\n        </div>\n        <div class=\"arrow\">➜</div>\n        <div class=\"desktop\">\n          <div class=\"deskicon\">🖥️</div>\n          <strong>Your Desktop</strong><br><span style=\"color:#5a6b7d\">let go here</span>\n        </div>\n      </div>\n      <p class=\"cap\">Illustration — a drawing: drag the highlighted file out of Cyberduck and drop it on your Desktop.</p>\n    </div>\n    <p><strong>The other way:</strong> right-click the file, click <strong>Download To…</strong>, pick where to put it, and click <strong>Choose</strong>.</p>\n\n    <h3>⏳ While it is copying…</h3>\n    <p>A small <strong>Transfers</strong> window appears and shows a moving bar. That bar is the file travelling to your computer.</p>\n    <div class=\"illus\" style=\"max-width:560px;margin-left:auto;margin-right:auto\">\n      <div class=\"win\">\n        <div class=\"winbar\">Transfers</div>\n        <div style=\"padding:14px 18px\">\n          <p style=\"margin:0 0 8px\">🎬 <strong>My-Big-Video.mp4</strong> — downloading…</p>\n          <div class=\"progress\"><div></div></div>\n          <p style=\"margin:6px 0 0;color:#5a6b7d\">The bar fills up as the file arrives. Full bar = finished.</p>\n        </div>\n      </div>\n      <p class=\"cap\">Illustration — a drawing of the Transfers window.</p>\n    </div>\n    <div class=\"callout warn\"><span class=\"ctitle\">🚫 Do NOT close Cyberduck while the bar is moving</span>\n    Closing Cyberduck stops the copy, and the file will be broken or missing. Big files can take a long time — that is normal. Let it finish. Go make a coffee.</div>\n  </section>\n\n  <section id=\"guide-step-8\">\n    <h2><span class=\"stepnum\">7</span> Where did my file go?</h2>\n    <ul class=\"big checklist\">\n      <li>✅ If you dragged it: look on your <strong>Desktop</strong> (or in the folder you dropped it on). It is there.</li>\n      <li>✅ If you used <strong>Download To…</strong>: it is in the folder you picked.</li>\n      <li>✅ <strong>How to know it finished:</strong> the Transfers window says the transfer is complete and the bar is full — and the file on your computer opens/plays when you double-click it.</li>\n      <li>⏳ For a big file, remember Step 5: after the bar fills, Cyberduck may spend some time <strong>sticking the pieces back together</strong> before the file appears. Wait for it.</li>\n      <li>⚠️ If the file will not open or will not play, the copy probably did not finish. Connect again and download it again, and this time wait for the full bar.</li>\n    </ul>\n  </section>\n\n  <section id=\"guide-step-9\">\n    <h2><span class=\"stepnum\">8</span> The rules (please read — they are short)</h2>\n    <div class=\"callout warn\"><span class=\"ctitle\">🚫 Do NOT delete, rename, or move anything</span>\n    The folder is shared, and everybody uses the <strong>same login</strong> — so if a file is deleted, renamed, or moved, <strong>there is no way to tell who did it</strong>. If you delete or rename a file, it is gone or changed <strong>for everybody</strong>, not just for you. Only ever <strong>copy files TO your computer</strong>. Never drag things around inside Cyberduck.</div>\n    <div class=\"callout warn\"><span class=\"ctitle\">🔑 Do NOT pass the login on to anyone</span>\n    Everyone the folder is shared with uses the same username and password (the box on page 1). Do not give it to anybody else — if someone asks for it, tell the person who gave you this guide instead. They decide who gets in.</div>\n    <div class=\"callout tip\"><span class=\"ctitle\">🔁 If the password ever changes, EVERYONE needs the new one</span>\n    Because it is one shared login, there is no “my password” and “your password” — there is just <em>the</em> password. If the password is changed, your old one will stop working, and everyone will be given the new one. Update the box on page 1 when that happens.</div>\n    <ul class=\"big\">\n      <li>✔️ You <strong>can</strong> download anything in the folder, as many times as you like.</li>\n      <li>✔️ When you are finished, just close Cyberduck. That logs you out. Nothing else to do.</li>\n    </ul>\n  </section>\n\n  <section id=\"guide-step-10\">\n    <h2><span class=\"stepnum\">9</span> Something went wrong?</h2>\n    <p>Read the words on your screen, find them below, and do what it says.</p>\n\n    <div class=\"callout info\"><span class=\"ctitle\">🔐 It says “Login failed”</span>\n    The username or password was typed wrong. Look at the <strong>box on page 1</strong> and copy it exactly. Check: <strong>Caps Lock</strong> off? No extra space at the start or end? Delete both boxes and type them again, slowly. (Also possible: the shared password was changed — ask the person who gave you this guide if there is a new one.)</div>\n\n    <div class=\"callout info\"><span class=\"ctitle\">⚠️ A certificate popup appeared</span>\n    That is expected — it is part of Step 3 of this guide. Click <strong>Continue</strong>. (Tick “Always trust” first if you see it.)</div>\n\n    <div class=\"callout info\"><span class=\"ctitle\">⏰ It hangs, spins, or says it timed out</span>\n    Your internet may have blinked. Close Cyberduck, check your internet works (open any website), then open Cyberduck and double-click your bookmark to try again.</div>\n\n    <div class=\"callout info\"><span class=\"ctitle\">🧩 A big download failed, or left a folder of pieces</span>\n    Do not start over. Open the <strong>Transfers</strong> window, click the failed download once, and click <strong>Resume</strong> — Cyberduck fetches only the missing pieces and then sticks them together. If you cancelled during the “sticking together” part at the very end, the file cannot be finished — download it again and this time let it sit until it is completely done.</div>\n\n    <div class=\"callout info\"><span class=\"ctitle\">🐢 Downloads are very slow</span>\n    Did you do Step 5? The segmented download box (Edit → Preferences → Transfers → General → Downloads) must be ticked. Tick it, then use <strong>Resume</strong> on the slow download — or start that one download again so it uses pieces.</div>\n\n    <div class=\"callout info\"><span class=\"ctitle\">🙋 Still stuck?</span>\n    Contact <strong>the person who gave you this guide</strong>. Tell them the <strong>exact words</strong> of the error message on your screen — take a photo of the screen if you can. “It doesn't work” is hard to fix; the exact words make it easy.</div>\n  </section>\n\n  <div class=\"callout ok\" style=\"margin-top:22px\"><span class=\"ctitle\">🎉 Quick reminder card</span>\n  Open <strong>Cyberduck</strong> → double-click <strong>your bookmark</strong> → click <strong>Continue</strong> on the popup → <strong>drag</strong> the file you want onto your <strong>Desktop</strong> → wait for the bar to finish → done.</div>\n\n  <div class=\"footer\">\n    Guide for a private shared folder (your-server.example.com) using Cyberduck from <a href=\"https://cyberduck.io/\" target=\"_blank\" rel=\"noopener noreferrer\">cyberduck.io</a>. All pictures in this guide are drawings/illustrations of what the real screens look like, not photos of anyone's computer. The shared username and password are written in the box on page 1.\n  </div>\n\n</div>\n<footer class=\"mh-guide-build\"><a href=\"/#shared-files\">← Back to Shared Files</a><span>ScreenDen · v1.0.0-rc.1 · Build: ScreenDen contributors</span></footer></body>\n</html>\n";
